// gerador-avatar-cirl — Lip-sync avatar via Seedance 2.0
// Input: { production_id, intro_prompt, outro_prompt,
//          intro_audio_public_url, outro_audio_public_url }
// Output: { production_id, intro_url, outro_url, intro_path, outro_path }
//
// Seedance 2.0: accepts image_urls[] + audio_urls[] → lip-synced talking head
// Audio baked into output video — no separate overlay needed in montagem

const https = require('https');
const http  = require('http');

let FAL_KEY = "443a6432-3b5b-4abe-a925-a6336817f13f:70f93e62dbc7def11558314850ea375c";
try { if ($env.FAL_KEY) FAL_KEY = $env.FAL_KEY; } catch(e) {}
const MONTAGEM_HOST = 'montagem';
const MONTAGEM_PORT = 3000;

// Cirlene reference images (uploaded to fal CDN)
const REF_IMGS = [
  "https://v3b.fal.media/files/b/0a9d190b/eJgcWqX9t4DJ2Ypx_1InI_IMG_3628.JPG",
  "https://v3b.fal.media/files/b/0a9d190d/MPANCIXNZroF4MEj3lQhq_IMG_3629.JPG",
  "https://v3b.fal.media/files/b/0a9d1911/2agE2ANEpIiKnJWbYge44_IMG_3631.JPG"
];

const body              = $input.first().json.body || $input.first().json;
const pid               = body.production_id;
const introPrompt       = body.intro_prompt;
const outroPrompt       = body.outro_prompt;
const introAudioUrl     = body.intro_audio_public_url;  // public MinIO URL accessible by fal.ai
const outroAudioUrl     = body.outro_audio_public_url;

if (!pid) throw new Error('production_id required');
if (!introAudioUrl) throw new Error('intro_audio_public_url required (run narracao first)');
if (!outroAudioUrl) throw new Error('outro_audio_public_url required (run narracao first)');

const sleep = ms => new Promise(r => setTimeout(r, ms));
const AUTH  = { 'Authorization': `Key ${FAL_KEY}` };

const MODEL      = 'bytedance/seedance-2.0/reference-to-video';
const FAL_HOST   = 'queue.fal.run';

function httpsReq(method, hostname, path, hdrs, payload) {
  return new Promise((resolve, reject) => {
    const data = payload ? JSON.stringify(payload) : null;
    const opts = {
      hostname, path, method,
      headers: { ...hdrs, ...(data ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } : {}) }
    };
    const req = https.request(opts, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => { try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body, status: res.statusCode }); } });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

function httpPost(host, port, path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const opts = {
      hostname: host, port, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
    };
    const req = http.request(opts, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => { try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body }); } });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function submitSeedance(prompt, audioUrl) {
  const r = await httpsReq('POST', FAL_HOST, `/${MODEL}`, AUTH, {
    prompt,
    image_urls: REF_IMGS,
    audio_urls: [audioUrl],
    duration: 'auto',
    aspect_ratio: '9:16',
    resolution: '720p'
  });
  if (!r.request_id) throw new Error(`Seedance submit failed: ${JSON.stringify(r).slice(0,300)}`);
  return r.request_id;
}

async function pollSeedance(requestId, label) {
  for (let i = 0; i < 60; i++) {  // up to 15 min
    await sleep(15000);
    const s = await httpsReq('GET', FAL_HOST, `/${MODEL}/requests/${requestId}/status`, AUTH, null);
    console.log(`[${pid}] ${label} poll ${i+1}: ${s.status}`);
    if (s.status === 'COMPLETED') {
      const res = await httpsReq('GET', FAL_HOST, `/${MODEL}/requests/${requestId}`, AUTH, null);
      console.log(`[${pid}] ${label} result keys: ${Object.keys(res).join(', ')}`);
      const videoUrl = res.video?.url || res.videos?.[0]?.url || res.output?.video?.url || res.output?.url;
      if (!videoUrl) throw new Error(`Seedance completed but no video URL. keys: ${Object.keys(res).join(',')} sample: ${JSON.stringify(res).slice(0,300)}`);
      return videoUrl;
    }
    if (s.status === 'FAILED') throw new Error(`Seedance ${label} failed: ${JSON.stringify(s)}`);
  }
  throw new Error(`Seedance ${label} polling timeout after 15min`);
}

async function uploadToMinio(falUrl, bucket, key) {
  const r = await httpPost(MONTAGEM_HOST, MONTAGEM_PORT, '/upload-from-url', { url: falUrl, bucket, key });
  if (r.error) throw new Error('upload failed: ' + r.error);
  return r;
}

// Submit INTRO and OUTRO in parallel (saves ~8 min vs sequential)
console.log(`[${pid}] Submitting INTRO + OUTRO to Seedance 2.0...`);
const [introId, outroId] = await Promise.all([
  submitSeedance(introPrompt, introAudioUrl),
  submitSeedance(outroPrompt, outroAudioUrl)
]);
console.log(`[${pid}] INTRO id: ${introId}`);
console.log(`[${pid}] OUTRO id: ${outroId}`);

// Poll both in parallel
const [introFalUrl, outroFalUrl] = await Promise.all([
  pollSeedance(introId, 'INTRO'),
  pollSeedance(outroId, 'OUTRO')
]);
console.log(`[${pid}] INTRO fal url: ${introFalUrl}`);
console.log(`[${pid}] OUTRO fal url: ${outroFalUrl}`);

// Upload both to MinIO
const [introResult, outroResult] = await Promise.all([
  uploadToMinio(introFalUrl, 'cirlene-video', `${pid}/intro.mp4`),
  uploadToMinio(outroFalUrl, 'cirlene-video', `${pid}/outro.mp4`)
]);

console.log(`[${pid}] Avatar done: intro=${introResult.path} outro=${outroResult.path}`);

return [{ json: {
  production_id: pid,
  intro_path: introResult.path, intro_url: introResult.url,
  outro_path: outroResult.path, outro_url: outroResult.url,
} }];
